    function highlightDialogue(text) {
        return text.split('“').map((seg, i) => {
            if (i === 0) return seg;
            const endIdx = seg.indexOf('”');
            if (endIdx !== -1) {
                return '<span class="quote-hl">“' + seg.substring(0, endIdx + 1) + '</span>' + seg.substring(endIdx + 1);
