            return '“' + seg;
        }).join('');
    }

    container.innerHTML = paragraphs.map((para, index) => {
        const isCutLine = index === 0 && /咔|收工|这条过/.test(para);
        const cls = isCutLine ? ' class="director-cut"' : '';
        return '<p' + cls + '>' + highlightDialogue(para) + '</p>';
    }).join('');
})();
