<script>
(function() {
    'use strict';

    const APP_CONFIG = {
        memoryKey: 'story_panel_strategy',
        defaultStrategy: 'concat'
    };

    class StoryController {
        constructor() {
            this.nodes = {
                board: document.getElementById('boardRoot'),
                payload: document.getElementById('sourcePayload'),
                track: document.getElementById('interactiveTrack'),
                toggles: document.querySelectorAll('.toggle-item'),
                accordion: document.getElementById('accordionTrigger'),
                foldable: document.getElementById('foldableArea'),
                selectorGroup: document.getElementById('strategySelectors')
            };

            this.currentStrategy = localStorage.getItem(APP_CONFIG.memoryKey) || APP_CONFIG.defaultStrategy;
            this.mount();
        }

        mount() {
            // 初始化时强制确保处于收纳状态
            if (this.nodes.foldable) {
                this.nodes.foldable.classList.add('hidden-zone');
                this.nodes.foldable.style.display = 'none';
            }
            this.buildUI();
            this.attachListeners();
            this.syncToggleVisuals();
        }

        extractData() {
            const rawContent = this.nodes.payload ? (this.nodes.payload.innerHTML || "") : "";
            const lines = rawContent.split('\n').map(str => str.trim()).filter(Boolean);

            return lines.map(line => {
                // 优先用正则精准匹配：【标签】：内容 或 1. [标签]: 内容（不再受 15 个字符长度限制）
                const bracketMatch = line.match(/^(?:\d+[\.\、\s]*)?[【\[]([^】\]]+)[】\]][\s]*[：:]([\s\S]*)$/);
                if (bracketMatch) {
                    return {
                        tag: bracketMatch[1].trim(),
                        text: bracketMatch[2].trim()
                    };
                }

                // 兜底匹配普通冒号分隔（将长度限制放宽到 30 字符以内）
                const idxCN = line.indexOf('：');
                const idxEN = line.indexOf(':');
                let separatorIndex = -1;
                if (idxCN !== -1 && idxEN !== -1) {
                    separatorIndex = Math.min(idxCN, idxEN);
                } else {
                    separatorIndex = Math.max(idxCN, idxEN);
                }

                if (separatorIndex > 0 && separatorIndex <= 30) {
                    let prefix = line.substring(0, separatorIndex).trim();
                    prefix = prefix.replace(/^\d+[\.\、\s]*/, '').replace(/^[【\[\s]+|[】\]\s]+$/g, '').trim();
                    return { tag: prefix, text: line.substring(separatorIndex + 1).trim() };
                }

                // 如果完全没有标签，去掉开头的序号直接显示
                return { tag: null, text: line.replace(/^\d+[\.\、\s]*/, '').trim() };
            });
        }

        buildUI() {
            const parsedItems = this.extractData();

            const htmlString = parsedItems.map((item) => {
                const tagMarkup = item.tag ? `<div class="pill-tag">${item.tag}</div>` : '';
                return `
                    <li class="choice-block" data-val="${encodeURIComponent(item.text)}">
                        ${tagMarkup}
                        <div class="detail-text">${item.text}</div>
                    </li>
                `;
            }).join('');

            if (this.nodes.track) {
                this.nodes.track.innerHTML = htmlString;
            }
        }

        attachListeners() {
            if (this.nodes.accordion && this.nodes.foldable) {
                this.nodes.accordion.addEventListener('click', () => {
                    const isHidden = this.nodes.foldable.classList.toggle('hidden-zone');
                    this.nodes.foldable.style.display = isHidden ? 'none' : 'block';
                    if (this.nodes.board) {
                        this.nodes.board.classList.toggle('is-collapsed', isHidden);
                    }
                });
            }

            if (this.nodes.selectorGroup) {
                this.nodes.selectorGroup.addEventListener('click', (e) => {
                    e.stopPropagation();
                    const targetBtn = e.target.closest('.toggle-item');
                    if (targetBtn) {
                        this.currentStrategy = targetBtn.dataset.strategy;
                        localStorage.setItem(APP_CONFIG.memoryKey, this.currentStrategy);
                        this.syncToggleVisuals();
                    }
                });
            }

            if (this.nodes.track) {
                this.nodes.track.addEventListener('click', (e) => {
                    const block = e.target.closest('.choice-block');
                    if (block) {
                        const textPayload = decodeURIComponent(block.dataset.val);
                        this.dispatchAction(textPayload);
                    }
                });
            }
        }

        syncToggleVisuals() {
            this.nodes.toggles.forEach(btn => {
                const isSelected = btn.dataset.strategy === this.currentStrategy;
                btn.classList.toggle('is-selected', isSelected);
            });
        }

        dispatchAction(text) {
            try {
                const pDoc = window.parent.document;
                const inputBox = pDoc.querySelector('#send_textarea');
                const apiTrigger = window.parent.triggerSlash;

                const executors = {
                    direct: () => {
                        if (apiTrigger) {
                            apiTrigger('/setinput ' + text);
                        } else if (inputBox) {
                            inputBox.value = text;
                            inputBox.dispatchEvent(new Event('input', { bubbles: true }));
                        }
                        setTimeout(() => {
                            const sendBtn = pDoc.querySelector('#send_but');
                            if (sendBtn) sendBtn.click();
                        }, 300);
                    },
                    concat: () => {
                        if (inputBox) {
                            const currentVal = inputBox.value.trim();
                            inputBox.value = currentVal ? `${currentVal} ${text}` : text;
                            inputBox.dispatchEvent(new Event('input', { bubbles: true }));
                        } else if (apiTrigger) {
                            apiTrigger('/setinput ' + text);
                        }
                    }
                };

                if (executors[this.currentStrategy]) {
                    executors[this.currentStrategy]();
                }

            } catch (err) {
                console.warn('跨域或DOM操作被拒绝', err);
            }
        }
    }

    try {
        new StoryController();
    } catch (e) {
        console.error("面板初始化失败:", e);
    }
})();
</script>
